SQL_DOC.P_SQL:

DECLARE

	V_COUNT				NUMBER;

BEGIN

	V_COUNT				:= 0;

	SELECT COUNT(*) INTO V_COUNT
	FROM KEP_NEED_T
	WHERE LOC_ID = $LOC_ID$
	;

	IF V_COUNT=0 THEN

		INSERT INTO KEP_NEED_T(
			LOC_ID,
			NAPPUM_DATE,
			IF_DATE
		) VALUES (
			$LOC_ID$,
			TO_DATE($NAPPUM_DATE$,'YYYYMMDD'),
			SYSDATE
		)
		;

	END IF;

END;
